import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const b=JSON.parse('{"title":"OCBL: troubleshooting and status codes","description":"","frontmatter":{},"headers":[],"relativePath":"components/ocbl/ocbl-troubleshooting.md","filePath":"components/ocbl/ocbl-troubleshooting.md"}'),s={name:"components/ocbl/ocbl-troubleshooting.md"};function d(i,e,n,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="ocbl-troubleshooting-and-status-codes" tabindex="-1">OCBL: troubleshooting and status codes <a class="header-anchor" href="#ocbl-troubleshooting-and-status-codes" aria-label="Permalink to &quot;OCBL: troubleshooting and status codes&quot;">​</a></h1><p>What OCBL and the recovery chain report, and what each report means.</p><h2 id="the-reserved-area-record-what-ocbl-writes" tabindex="-1">The reserved-area record (what OCBL writes) <a class="header-anchor" href="#the-reserved-area-record-what-ocbl-writes" aria-label="Permalink to &quot;The reserved-area record (what OCBL writes)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>magic</code> / <code>ver</code> / <code>size</code></td><td><code>&quot;OCB1&quot;</code>, version 1, 28-byte layout</td></tr><tr><td><code>kind</code></td><td>the record kind (below)</td></tr><tr><td><code>stall</code></td><td>the stage where the boot hung</td></tr><tr><td><code>seq</code></td><td>the state area&#39;s boot-attempt sequence at judgment time</td></tr><tr><td><code>ts_unix</code></td><td>judgment time, unix seconds (CMOS)</td></tr><tr><td><code>silence_sec</code></td><td>the measured no-progress seconds</td></tr><tr><td><code>routed</code></td><td>1 = OCBL already auto-booted OCIRE</td></tr><tr><td><code>boot_fails</code></td><td>consecutive judged failures</td></tr><tr><td><code>checksum</code></td><td>ones-complement sum of the preceding payload words - the check that separates a real record from reset garbage</td></tr></tbody></table><h3 id="record-kinds" tabindex="-1">Record kinds <a class="header-anchor" href="#record-kinds" aria-label="Permalink to &quot;Record kinds&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kind</th><th>Meaning</th></tr></thead><tbody><tr><td>NONE</td><td>no record (a normal boot)</td></tr><tr><td>BOOT_FAILED</td><td>a watchdog-caught, judged boot failure</td></tr><tr><td>USER_REQUEST</td><td>the user chose the OCIRE entry in the menu</td></tr><tr><td>WAKE_FAILED</td><td>SLEEP_ARMED survived a reboot (wake vector crash or death mid-sleep)</td></tr></tbody></table><h2 id="the-takeover-menus-in-ocire-after-routing" tabindex="-1">The takeover menus (in OCIRE, after routing) <a class="header-anchor" href="#the-takeover-menus-in-ocire-after-routing" aria-label="Permalink to &quot;The takeover menus (in OCIRE, after routing)&quot;">​</a></h2><p>Two blocking menus share one key loop. <strong>Every other key is ignored and there is no timeout</strong> - the machine stays in recovery until a human decides.</p><h3 id="boot-failed-takeover-two-consecutive-judged-failures" tabindex="-1">Boot-failed takeover (two consecutive judged failures) <a class="header-anchor" href="#boot-failed-takeover-two-consecutive-judged-failures" aria-label="Permalink to &quot;Boot-failed takeover (two consecutive judged failures)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[R] Rollback to the previous OCOS version</span></span>
<span class="line"><span>[C] Continue and try booting OCOS again</span></span></code></pre></div><h3 id="wake-failed-takeover-sleep-armed-survived-a-reboot" tabindex="-1">Wake-failed takeover (SLEEP_ARMED survived a reboot) <a class="header-anchor" href="#wake-failed-takeover-sleep-armed-survived-a-reboot" aria-label="Permalink to &quot;Wake-failed takeover (SLEEP_ARMED survived a reboot)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[W] Wake from sleep failed.   (diagnostics)</span></span>
<span class="line"><span>[R] Rollback to the previous OCOS version</span></span>
<span class="line"><span>[C] Try to boot OCOS normally</span></span></code></pre></div><ul><li><code>[R]</code> flips the OCOS A/B slot flags (the <code>next_B</code> / <code>ok_B</code> / <code>bootfail_B</code> protocol - the same semantics the GRUB config and OCBL&#39;s scanner implement) and reboots.</li><li><code>[C]</code> clears the failure record and reboots into OCOS.</li><li><code>[W]</code> shows the wake-failure diagnostics.</li></ul><h2 id="reading-a-boot-failure" tabindex="-1">Reading a boot failure <a class="header-anchor" href="#reading-a-boot-failure" aria-label="Permalink to &quot;Reading a boot failure&quot;">​</a></h2><p>OCIRE prints the record&#39;s fields as repair advice: the stall stage (0 BOOT / 1 KMAIN / 2 SCHED / 3 DRIVERS / 4 SERVICES / 5 L1_LAUNCHED / 6 L1_READY / 255 RUNTIME), the measured silence, the boot-failure count and the boot sequence. A stall in the low stages with a large <code>silence_sec</code> points at hardware or early kernel trouble; a stall at 255 (RUNTIME) means the system came up and hung later.</p><h2 id="the-hangat-diagnostic-hook" tabindex="-1">The /HANGAT diagnostic hook <a class="header-anchor" href="#the-hangat-diagnostic-hook" aria-label="Permalink to &quot;The /HANGAT diagnostic hook&quot;">​</a></h2><p>When a one-byte file <code>/HANGAT</code> containing <code>1</code>..<code>7</code> exists on the payload volume, OCBL appends <code>oc.hang=N</code> to the kernel command line and the kernel deliberately halts right after recording stage N - with the phase watchdog armed, so the real watchdog -&gt; reset -&gt; diagnosis chain fires exactly as it would in production. <code>7</code> halts after L1_READY with the runtime heartbeat running (the runtime-hang scenario). The hook exists so <strong>shipped images</strong> can be failure-tested without test-built kernels; with no file present it is a complete no-op.</p><h2 id="when-the-monitor-disables-itself" tabindex="-1">When the monitor disables itself <a class="header-anchor" href="#when-the-monitor-disables-itself" aria-label="Permalink to &quot;When the monitor disables itself&quot;">​</a></h2><p>If the fixed monitor pages are not free for OCBL this boot (BIOS: no E820 usable region covers them; UEFI: the AllocatePages reserve failed), the whole monitor <strong>disables for that boot</strong> - no low-memory writes at all - and the kernel learns it from the <code>oc.stmon=off</code> command-line flag.</p><h2 id="the-declared-uefi-watchdog-limitation" tabindex="-1">The declared UEFI watchdog limitation <a class="header-anchor" href="#the-declared-uefi-watchdog-limitation" aria-label="Permalink to &quot;The declared UEFI watchdog limitation&quot;">​</a></h2><p>With the i6300ESB PCI watchdog device attached, the UEFI (OVMF) OCBL payload path dies after the slot scan; a controlled rebuild of the unmodified pre-WP07 loader fails byte-identically, so the defect predates WP-07. Without the device the entire UEFI monitor path is verified live. The <strong>BIOS flavor carries the complete verified watchdog mechanism</strong> and must pass fully (it does). See <a href="./../../root/KNOWN_ISSUES.html">KNOWN_ISSUES</a> K-02.</p><h2 id="consistency-with-the-ocire-recovery-flow" tabindex="-1">Consistency with the OCIRE recovery flow <a class="header-anchor" href="#consistency-with-the-ocire-recovery-flow" aria-label="Permalink to &quot;Consistency with the OCIRE recovery flow&quot;">​</a></h2><p>The recovery chain the menus guard is the WP-07 closed loop: the strictly <strong>manual</strong> <code>update</code> command (no network, no timers) reads <code>\\EFI\\OpenCube\\ocire-update.bin</code> and its <code>.sig</code> from the real GPT ESP, verifies the signature with the built-in <strong>Ed25519</strong> public key, flashes the <strong>inactive</strong> slot of the two-partition recovery disk, hashes the read-back, and arms it via the A/B flags sector at LBA 1024. A bad image never replaces the running slot - the takeover menus exist for the case where the <em>running system</em> fails, not the update path.</p><p>See also: <a href="./ocbl-ab.html">dual-firmware boot and A/B slot decisions</a> for the flags-sector and state-area semantics.</p>`,24)])])}const p=t(s,[["render",d]]);export{b as __pageData,p as default};
